mapper.update:
UPDATE work_assignment 
SET status = #{status}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}

mapper.select:
SELECT DISTINCT student_id FROM work_assignment
WHERE work_date = #{workDate} AND time_slot = #{timeSlot}
AND status IN ('assigned', 'checked_in', 'pending_confirmation')

SELECT * FROM work_assignment
WHERE job_id = #{jobId}
  AND student_id = #{studentId}
  AND status IN ('assigned', 'checked_in')

SELECT id FROM work_assignment
WHERE student_id = #{studentId}
  AND job_id = #{jobId}
  AND work_date = #{workDate}
  AND time_slot = #{timeSlot}
  AND status IN ('assigned', 'checked_in', 'pending_confirmation')
    LIMIT 1

SELECT DISTINCT work_date, time_slot
FROM work_assignment
WHERE student_id = #{studentId}
AND work_date >= #{fromDate}
AND status IN ('assigned', 'checked_in', 'pending_confirmation')

SELECT wa.id
FROM work_assignment wa
WHERE wa.student_id = #{studentId}
  AND wa.status IN ('assigned', 'checked_in')
  AND DAYOFWEEK(wa.work_date) = #{dayOfWeek}
  AND wa.time_slot = #{timeSlot}
